from __future__ import annotations

from datetime import date
from decimal import Decimal, ROUND_HALF_UP, localcontext


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO YYYY-MM-DD format."""
    if yyyymmdd in (None, "", "00000000"):
        return None

    if (
        not isinstance(yyyymmdd, str)
        or len(yyyymmdd) != 8
        or not yyyymmdd.isdigit()
    ):
        raise ValueError("legacy date must be YYYYMMDD")

    try:
        parsed = date(
            int(yyyymmdd[0:4]),
            int(yyyymmdd[4:6]),
            int(yyyymmdd[6:8]),
        )
    except ValueError as exc:
        raise ValueError("legacy date must be a valid YYYYMMDD date") from exc

    return parsed.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to the legacy YYYYMMDD representation."""
    if iso in (None, ""):
        return "00000000"

    if (
        not isinstance(iso, str)
        or len(iso) != 10
        or iso[4] != "-"
        or iso[7] != "-"
        or not (iso[0:4] + iso[5:7] + iso[8:10]).isdigit()
    ):
        raise ValueError("ISO date must be YYYY-MM-DD")

    try:
        parsed = date(
            int(iso[0:4]),
            int(iso[5:7]),
            int(iso[8:10]),
        )
    except ValueError as exc:
        raise ValueError("ISO date must be a valid YYYY-MM-DD date") from exc

    return parsed.strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert the legacy Y/N flag, treating blank and None as N."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to rounded currency minor units."""
    if amount in (None, ""):
        return 0

    effective_currency = "USD" if currency in (None, "") else currency
    exponent = 0 if effective_currency == "JPY" else 2

    value = Decimal(str(amount))
    if not value.is_finite():
        raise ValueError("amount must be a finite decimal value")

    quantum = Decimal(1).scaleb(-exponent)
    required_precision = max(28, len(value.as_tuple().digits) + exponent + 2)

    with localcontext() as context:
        context.prec = required_precision
        rounded = value.quantize(quantum, rounding=ROUND_HALF_UP)
        return int(rounded.scaleb(exponent))
